import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());
        long[] b = new long[(int) m];
        for (int i = 0; i < b.length; i++) b[i] = Long.parseLong(next());

        Map<Long, Integer> count = new HashMap<>();
        for (int i = 0; i < n; i++) count.merge(a[i], 1, Integer::sum);
        List<Long> result = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            int c = count.getOrDefault(b[i], 0);
            if (c > 0) {
                result.add(b[i]);
                count.put(b[i], c - 1);
            }
        }
        Collections.sort(result);
        StringBuilder sb = new StringBuilder();
        for (long v : result) sb.append(v).append(" ");
        System.out.println(result.size());
        System.out.println(sb.toString().trim());
    }
}
